#!/usr/bin/env python3
"""Warn before a large generated file is committed.

History is what makes this repository expensive: the two Git packs hold ~600 MB
because several complete release packages were committed one after another.
Removing them from the working tree does not shrink history — only *not
committing them again* does.

This guard inspects the **staged** files (what `git commit` would add) and warns
about blobs that look like build output rather than source. It is deliberately
warn-only by default: a legitimate large asset (a fixture PDF, a font) must not
be blocked by an arbitrary limit. Use `--strict` in CI if you want a hard gate.

Usage
-----
    python scripts/size_guard.py            # warn, always exit 0
    python scripts/size_guard.py --strict   # exit 1 on any finding

As a pre-commit hook (opt-in, one command)::

    git config core.hooksPath .githooks
"""

from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

#: A single staged file this large is almost certainly generated.
BIG_FILE_BYTES = 50 * 1024 * 1024
#: Lots of medium files is the same mistake spread out.
MEDIUM_FILE_BYTES = 5 * 1024 * 1024
MEDIUM_FILE_COUNT = 20

#: Paths that are regenerated by the release pipeline; committing them is what
#: inflated this repository in the first place.
GENERATED_PREFIXES = (
    "MathChecker_Distribution/portable/",
    "MathChecker_Distribution/release_staging/",
    "MathChecker_Distribution/previous_builds/",
    "MathChecker_Distribution/build/",
    "frontend/node_modules/",
    "frontend/dist/",
    ".venv",
    "data/",
)


def human(num: int) -> str:
    value = float(num)
    for unit in ("B", "KiB", "MiB", "GiB"):
        if value < 1024 or unit == "GiB":
            return f"{int(value):,} B" if unit == "B" else f"{value:,.1f} {unit}"
        value /= 1024
    return f"{num:,} B"


def staged_blobs() -> list[tuple[str, int]]:
    """Return ``(path, size_in_index)`` for every added/modified staged file."""
    try:
        listing = subprocess.run(
            ["git", "diff", "--cached", "--name-only", "--diff-filter=AM", "-z"],
            cwd=ROOT, capture_output=True, check=True,
        ).stdout.decode("utf-8", "replace")
    except (OSError, subprocess.CalledProcessError) as exc:
        print(f"size_guard: cannot list staged files ({exc})", file=sys.stderr)
        return []

    paths = [p for p in listing.split("\0") if p]
    if not paths:
        return []

    # Map the staged path to the blob that is actually in the index, so the size
    # reported is the size that would enter history (not the working-tree file
    # and not a path that git cannot resolve as an object).
    index_shas: dict[str, str] = {}
    try:
        entries = subprocess.run(
            ["git", "ls-files", "-s", "-z"],
            cwd=ROOT, capture_output=True, check=True,
        ).stdout.decode("utf-8", "replace").split("\0")
        for entry in entries:
            if not entry:
                continue
            meta, _, path = entry.partition("\t")
            fields = meta.split()
            if len(fields) >= 2:
                index_shas[path] = fields[1]
    except (OSError, subprocess.CalledProcessError):
        index_shas = {}

    sized: list[tuple[str, str]] = [(p, index_shas[p]) for p in paths if p in index_shas]
    sizes: list[tuple[str, int]] = []
    if sized:
        try:
            out = subprocess.run(
                ["git", "cat-file", "--batch-check=%(objectsize)"],
                cwd=ROOT,
                input="".join(sha + "\n" for _, sha in sized).encode(),
                capture_output=True, check=True,
            ).stdout.decode("utf-8", "replace")
            for (path, _sha), line in zip(sized, out.splitlines()):
                try:
                    sizes.append((path, int(line.strip())))
                except ValueError:
                    continue
        except (OSError, subprocess.CalledProcessError):
            pass

    if len(sizes) != len(paths):
        known = {path for path, _ in sizes}
        for path in paths:
            if path in known:
                continue
            try:
                sizes.append((path, (ROOT / path).stat().st_size))
            except OSError:
                continue
    return sizes


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--strict", action="store_true",
                        help="exit 1 when a finding is reported")
    parser.add_argument("--big-bytes", type=int, default=BIG_FILE_BYTES)
    args = parser.parse_args(argv)

    sizes = staged_blobs()
    findings: list[str] = []

    for path, size in sizes:
        if size >= args.big_bytes:
            findings.append(f"large staged file ({human(size)}): {path}")
        elif size >= MEDIUM_FILE_BYTES and path.replace("\\", "/").startswith(GENERATED_PREFIXES):
            findings.append(f"generated artifact staged ({human(size)}): {path}")

    medium = [p for p, s in sizes if s >= MEDIUM_FILE_BYTES]
    generated_tree = [
        p for p, _ in sizes
        if p.replace("\\", "/").startswith(GENERATED_PREFIXES)
    ]
    if len(medium) >= MEDIUM_FILE_COUNT:
        findings.append(f"{len(medium)} staged files are >= {human(MEDIUM_FILE_BYTES)}")
    if generated_tree:
        findings.append(
            f"{len(generated_tree)} staged file(s) sit under a generated/rebuilt "
            f"directory (e.g. {generated_tree[0]})")

    if not findings:
        return 0

    print("size_guard: this commit grows the repository more than expected:",
          file=sys.stderr)
    for finding in findings:
        print(f"  - {finding}", file=sys.stderr)
    print("\nBuild output belongs in release/ only; history cannot be shrunk by\n"
          "deleting it later. See docs/size_optimization/README.md.",
          file=sys.stderr)
    return 1 if args.strict else 0


if __name__ == "__main__":
    raise SystemExit(main())
